/* Uses the retained ARM64 GLib headers and runtime, not a signal model. */
#include <gio/gio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct { GApplication parent; } ProbeApplication;
typedef struct { GApplicationClass parent; } ProbeApplicationClass;
G_DEFINE_TYPE(ProbeApplication, probe_application, G_TYPE_APPLICATION)
static const char *log_path;
static int bad;
static int has(const char *marker)
{
    char bytes[1537];
    FILE *f = fopen(log_path, "r");
    if (!f) { bad = 1; return 0; }
    size_t n = fread(bytes, 1, sizeof(bytes)-1, f);
    bytes[n] = 0;
    if (ferror(f) || fclose(f)) bad = 1;
    return strstr(bytes, marker) != NULL;
}
static void activate(GApplication *app) { g_application_quit(app); }
static void shutdown_app(GApplication *app)
{
    if (!has("phase=SHUTDOWN_BEFORE ") || has("phase=SHUTDOWN_AFTER ")) bad = 1;
    g_settings_sync();
    G_APPLICATION_CLASS(probe_application_parent_class)->shutdown(app);
    if (has("phase=SHUTDOWN_AFTER ")) bad = 1;
}
static void probe_application_class_init(ProbeApplicationClass *klass)
{
    GApplicationClass *app = G_APPLICATION_CLASS(klass);
    app->activate = activate;
    app->shutdown = shutdown_app;
}
static void probe_application_init(ProbeApplication *self) { (void)self; }
int main(int argc, char **argv)
{
    if (argc != 2) return 2;
    log_path = argv[1];
    GApplication *app = g_object_new(probe_application_get_type(),
        "application-id", "org.rog5.ShutdownProbe", "flags", G_APPLICATION_NON_UNIQUE, NULL);
    int result = g_application_run(app, 1, argv);
    if (!has("phase=SHUTDOWN_AFTER ") || !has("phase=APP_RUN_END ")) bad = 1;
    g_object_unref(app);
    if (result || bad) return 3;
    puts("PASS real ARM64 GApplication RUN_LAST shutdown bracket and run return");
    return 0;
}

